layer.css:
[data-ryt="pitch"] { color: rgb(128, 128, 128); border-left: 5px solid rgb(238, 238, 238); border-radius: 0px; font-size: 16.15px; font-weight: 400; font-style: italic; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(128, 128, 128); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 10px; padding-right: 20px; padding-bottom: 10px; padding-left: 20px; transition: color 0.3s, background-color 0.3s, border-color 0.3s; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s, background-color 0.3s, border-color 0.3s }
[data-ryt="brand"] { color: #8c8c8c; border-radius: 0px; font-size: 18px; font-weight: 800; font-style: normal; line-height: 1.111; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s, background-color 0.3s, border-color 0.3s }
[data-ryt="review"] { color: #8f8f8f; font-size: 15px; font-weight: 400; font-style: italic; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(163, 163, 163); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s, background-color 0.3s, border-color 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s, background-color 0.3s, border-color 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-size: 26px; font-weight: 700; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s, background-color 0.3s, border-color 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #0085a1; color: #0085a1; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #0085a1 }
[data-ryt="review"]:hover { color: #0085a1 }
[data-ryt="brand"]:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(94, 94, 94); background-color: transparent; color: #0085a1 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #0085a1; color: #0085a1 }
